import{_ as t,o as e,c as r,a2 as o}from"./chunks/framework.CANn83f8.js";const i="/images/features/transactions-list.png",n="/images/features/import-bank-statement.png",u=JSON.parse('{"title":"Transactions","description":"","frontmatter":{},"headers":[],"relativePath":"features/transactions.md","filePath":"features/transactions.md","lastUpdated":1790713879000}'),s={name:"features/transactions.md"};function l(c,a,p,h,m,d){return e(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="transactions" tabindex="-1">Transactions <a class="header-anchor" href="#transactions" aria-label="Permalink to &quot;Transactions&quot;">​</a></h1><p>ExpenseAutomator can Import, search and manage all your transactions.</p><p>Transactions are the base foundation of ExpenseAutomator. Every time money comes in, or money comes out of your accounts, a transaction is recorded in the system. The transactions page provides an interface for viewing, filtering, and managing all your financial activity.</p><p><img src="'+i+'" alt="Transactions List"></p><h2 id="transaction-list" tabindex="-1">Transaction List <a class="header-anchor" href="#transaction-list" aria-label="Permalink to &quot;Transaction List&quot;">​</a></h2><p>The transaction list shows a table containing all your financial activity. Each row display the date, description, account, category, tags and the amount.</p><p>For positive amounts (income), we will display it in green, and for negative amounts (expense) in red.</p><h3 id="filters" tabindex="-1">Filters <a class="header-anchor" href="#filters" aria-label="Permalink to &quot;Filters&quot;">​</a></h3><p>There are several filters available on the transactions list.</p><ul><li>Search bar: search by merchant, description or tag</li><li>Calendar filter: All Time, Today, Yesterday, This Week, Last Week, This Month, Last Month, This Year, Last Year and Custom Range.</li><li>Banks Filter: Search by all banks on which a transaction was recorded</li><li>Categories filter: Search by budgets or categories</li><li>Transaction Type filter: Search by Income or Expense</li></ul><h2 id="import-csv" tabindex="-1">Import CSV <a class="header-anchor" href="#import-csv" aria-label="Permalink to &quot;Import CSV&quot;">​</a></h2><p>ExpenseAutomator allows you to bulk import transactions using CSV files. The list of supported banks are listed <a href="/features/banks">here</a>.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Unless instructed otherwise, do not edit exported files or change their data before importing them.</p></div><h2 id="import-workflow" tabindex="-1">Import workflow <a class="header-anchor" href="#import-workflow" aria-label="Permalink to &quot;Import workflow&quot;">​</a></h2><ol><li>Click on <strong>Import CSV</strong> located in the top right corner.</li><li>Select the CSV statement.</li><li>Click on <strong>Import CSV</strong><img src="'+n+'" alt="Import Bank Statement"></li><li>After the file import is completed. We show the Bank and number of transactions imported.</li></ol><h2 id="after-importing" tabindex="-1">After importing <a class="header-anchor" href="#after-importing" aria-label="Permalink to &quot;After importing&quot;">​</a></h2><p>Check the imported date range, transaction count, and totals. Resolve any uncategorized entries before relying on reports or budget comparisons.</p>',17)])])}const g=t(s,[["render",l]]);export{u as __pageData,g as default};
